// Menu of QtQuick.Templates. What is expected here is what Qt 6.11 noted and
// answered when a QtTest `TestCase` made the same moves in the same scene.
import { play } from "./moves.js";
import { expect, open, test } from "./open.js";

test("a Menu has a current item under the mouse and the arrow keys, opens its sub-menus and closes with what is triggered", async ({ page }) => {
  await play(page, "popupmenus", MENUS);
});

// Where the mouse is Qt's own test cannot say, so this is not Qt's answer but
// what its `popup()` does with `QCursor::pos()`: the menu opens at the mouse,
// in the item it opens over, with the item that is to be current there.
test("a Menu with no place said opens where the mouse is, and in the middle of its parent with no mouse", async ({ page }) => {
  await open(page, "popupmenus");
  const step = (index) =>
    page.evaluate((index) => {
      window.scene.step(index);
      const [main, , , , , extra] = window.scene.state();
      return [window.scene.take(), main.slice(1, 13), extra.slice(1, 13)];
    }, index);
  const closed = [false, false, 0, 0, 100, 24, 1, -1, true, 17, false, "root"];
  expect(await step(26)).toEqual([
    ["Extra aboutToShow"],
    [false, false, 0, 0, 100, 108, 6, -1, true, 17, false, "anchor"],
    [true, true, 150, 138, 100, 24, 1, -1, true, 17, true, "root"],
  ]);
  // `anchor` is at 30, 20.
  await page.mouse.move(120, 90);
  expect(await step(2)).toEqual([
    ["Extra closed", "Main aboutToShow"],
    [true, true, 90, 70, 100, 108, 6, -1, true, 17, true, "anchor"],
    [false, false, 150, 138, ...closed.slice(4)],
  ]);
  await step(1);
  await page.mouse.move(40, 150);
  expect((await step(6)).slice(0, 2)).toEqual([["Main aboutToShow"], [true, true, 10, 130, 100, 108, 6, -1, true, 17, true, "anchor"]]);
  await step(1);
  // The first item is two under the top of the menu.
  expect((await step(7)).slice(0, 2)).toEqual([
    ["Main current 0", "Main aboutToShow"],
    [true, true, 10, 128, 100, 108, 6, 0, true, 17, true, "anchor"],
  ]);
});

